  ["/sam settings — options, rôles et spécialisations"] = "/sam settings — options, rôles et spécialisations",
  ["1. Reproduis le problème avec la fenêtre concernée ouverte : maître de classe, marchand ou sacs."] = "1. Reproduis le problème avec la fenêtre concernée ouverte : maître de classe, marchand ou sacs.",
  ["2. Ouvre le rapport correspondant, puis utilise son export pour copier le texte."] = "2. Ouvre le rapport correspondant, puis utilise son export pour copier le texte.",
  ["3. Si nécessaire, compare après avoir désactivé manuellement un addon suspect et rechargé l'interface. Un addon présent dans le rapport n'est pas une preuve de conflit."] = "3. Si nécessaire, compare après avoir désactivé manuellement un addon suspect et rechargé l'interface. Un addon présent dans le rapport n'est pas une preuve de conflit.",
  ["A maintenir si combats contre morts-vivants ou demons."] = "A maintenir si combats contre morts-vivants ou demons.",
  ["ALREADY KNOWN : recettes déjà apprises dans les sacs et les jets de dés reconnus."] = "ALREADY KNOWN : recettes déjà apprises dans les sacs et les jets de dés reconnus.",
  ["ALREADY KNOWN signale automatiquement les recettes déjà apprises dans les sacs et les fenêtres de jet de dés de groupe ou raid, lorsque l’infobulle du jeu le confirme."] = "ALREADY KNOWN signale automatiquement les recettes déjà apprises dans les sacs et les fenêtres de jet de dés de groupe ou raid, lorsque l’infobulle du jeu le confirme.",
  ["Absorbe des dégâts et sécurise les incantations dans les deux activités."] = "Absorbe des dégâts et sécurise les incantations dans les deux activités.",
  ["Accéder aux rapports copiables du grimoire, des maîtres, des familiers et de compatibilité depuis Diagnostics."] = "Accéder aux rapports copiables du grimoire, des maîtres, des familiers et de compatibilité depuis Diagnostics.",
  ["Accélère les incantations après un critique, pour soigner ou attaquer."] = "Accélère les incantations après un critique, pour soigner ou attaquer.",
  ["Active séparément les ajouts visuels de l'addon. Ces choix sont enregistrés pour ce personnage et s'appliquent immédiatement aux fenêtres ouvertes ; les icônes et textes du jeu restent disponibles."] = "Active séparément les ajouts visuels de l'addon. Ces choix sont enregistrés pour ce personnage et s'appliquent immédiatement aux fenêtres ouvertes ; les icônes et textes du jeu restent disponibles.",
  ["Active « Afficher tous les rangs » dans les options du grimoire du jeu pour voir les anciens rangs. Exemple : Plaie d'agonie affiche BEST sur le plus haut rang appris et LOW sur les autres, sans ECO."] = "Active « Afficher tous les rangs » dans les options du grimoire du jeu pour voir les anciens rangs. Exemple : Plaie d'agonie affiche BEST sur le plus haut rang appris et LOW sur les autres, sans ECO.",
  ["Activer les conseils ECO"] = "Activer les conseils ECO",
  ["Activer ou désactiver les icônes, contours, textes et fonds de statut depuis Affichage, avec des explications et des aperçus."] = "Activer ou désactiver les icônes, contours, textes et fonds de statut depuis Affichage, avec des explications et des aperçus.",
  ["Activité"] = "Activité",
  ["Actualisation des marqueurs lorsque les livres sont déplacés ou que les sorts du familier changent."] = "Actualisation des marqueurs lorsque les livres sont déplacés ou que les sorts du familier changent.",
  ["Actualiser"] = "Actualiser",
  ["Actualiser les marqueurs"] = "Actualiser les marqueurs",
  ["Affaiblissement et dégâts utiles en PvE comme contre les joueurs."] = "Affaiblissement et dégâts utiles en PvE comme contre les joueurs.",
  ["Affaiblissements et protections utiles pour sécuriser les combats."] = "Affaiblissements et protections utiles pour sécuriser les combats.",
  ["Affaiblit les ennemis sensibles ; intérêt aussi en soutien PvE."] = "Affaiblit les ennemis sensibles ; intérêt aussi en soutien PvE.",
  ["Affichage"] = "Affichage",
  ["Affichage : icônes par zone, contours, textes et fonds réglables séparément."] = "Affichage : icônes par zone, contours, textes et fonds réglables séparément.",
  ["Affichage plus fluide et moins de défauts visuels pendant le défilement des sorts chez le maître de classe."] = "Affichage plus fluide et moins de défauts visuels pendant le défilement des sorts chez le maître de classe.",
  ["Afficher ALREADY KNOWN dans les sacs et les fenêtres de jet de dés lorsque l’infobulle du jeu confirme que la recette est déjà connue. Aucun survol ni scan de métier n’est nécessaire. L’absence de cette indication ne signifie pas que la recette est apprenable."] = "Afficher ALREADY KNOWN dans les sacs et les fenêtres de jet de dés lorsque l’infobulle du jeu confirme que la recette est déjà connue. Aucun survol ni scan de métier n’est nécessaire. L’absence de cette indication ne signifie pas que la recette est apprenable.",
  ["Afficher ALREADY KNOWN sur les recettes déjà apprises dans les fenêtres de butin du jeu. Ne change aucun choix Besoin, Cupidité ou Passer."] = "Afficher ALREADY KNOWN sur les recettes déjà apprises dans les fenêtres de butin du jeu. Ne change aucun choix Besoin, Cupidité ou Passer.",
  ["Afficher BUY NEW RANK sur le plus haut rang appris si un rang supérieur est accessible à ton niveau et n'est pas classé facultatif pour ton rôle. Les prix ne sont pas vérifiés. Catalogue fourni par TrainerSpells s'il est chargé ; sinon, informations observées chez le maître actuellement ouvert. Les données incertaines n'entraînent pas d'alerte."] = "Afficher BUY NEW RANK sur le plus haut rang appris si un rang supérieur est accessible à ton niveau et n'est pas classé facultatif pour ton rôle. Les prix ne sont pas vérifiés. Catalogue fourni par TrainerSpells s'il est chargé ; sinon, informations observées chez le maître actuellement ouvert. Les données incertaines n'entraînent pas d'alerte.",
  ["Afficher NEW +, la coche, NEXT, NOT NOW, ECO, BEST, OPTIONAL, BUY NEW RANK et LOW, ainsi que les marqueurs de livres et de démons. Désactiver retire aussi le halo de NEW + et les surimpressions assombries ; les icônes d'origine restent visibles."] = "Afficher NEW +, la coche, NEXT, NOT NOW, ECO, BEST, OPTIONAL, BUY NEW RANK et LOW, ainsi que les marqueurs de livres et de démons. Désactiver retire aussi le halo de NEW + et les surimpressions assombries ; les icônes d'origine restent visibles.",
  ["Afficher RECENT sur les recettes récemment apprises dans les listes de métiers du jeu reconnues."] = "Afficher RECENT sur les recettes récemment apprises dans les listes de métiers du jeu reconnues.",
  ["Afficher le bouton de minicarte"] = "Afficher le bouton de minicarte",
  ["Afficher le résumé et la liste des commandes dans une fenêtre séparée."] = "Afficher le résumé et la liste des commandes dans une fenêtre séparée.",
  ["Afficher les badges des sorts, les icônes de la légende et l’indication de rôle à gauche du titre de spécialisation du grimoire."] = "Afficher les badges des sorts, les icônes de la légende et l’indication de rôle à gauche du titre de spécialisation du grimoire.",
  ["Afficher les badges des sorts, les repères PVP / PVE PVP, les surimpressions et le halo NEW + chez le maître de classe."] = "Afficher les badges des sorts, les repères PVP / PVE PVP, les surimpressions et le halo NEW + chez le maître de classe.",
  ["Afficher les conseils OPTIONAL"] = "Afficher les conseils OPTIONAL",
  ["Afficher les indications de rôle à côté des titres et les repères PVP / PVE PVP sur les talents, avec leurs infobulles."] = "Afficher les indications de rôle à côté des titres et les repères PVP / PVE PVP sur les talents, avec leurs infobulles.",
  ["Afficher les marqueurs de livres dans les sacs, la banque et la banque de guilde, y compris les sacs EllesmereUI."] = "Afficher les marqueurs de livres dans les sacs, la banque et la banque de guilde, y compris les sacs EllesmereUI.",
  ["Afficher les marqueurs de livres et de démons chez le marchand."] = "Afficher les marqueurs de livres et de démons chez le marchand.",
  ["Afficher les repères PVP / PVE PVP"] = "Afficher les repères PVP / PVE PVP",
  ["Afficher séparément les icônes par zone : grimoire, maître de classe, marchand, sacs et banques, arbre de talents."] = "Afficher séparément les icônes par zone : grimoire, maître de classe, marchand, sacs et banques, arbre de talents.",
  ["Affliction offre une progression régulière avec les dégâts sur la durée et les drains. Démonologie devient plus intéressante lorsque ses talents renforçant le démon sont obtenus ; son début de parcours est plus lent."] = "Affliction offre une progression régulière avec les dégâts sur la durée et les drains. Démonologie devient plus intéressante lorsque ses talents renforçant le démon sont obtenus ; son début de parcours est plus lent.",
  ["Aide surtout à se dégager des joueurs au corps à corps."] = "Aide surtout à se dégager des joueurs au corps à corps.",
  ["Aide à continuer ses incantations lorsque l’on subit des attaques."] = "Aide à continuer ses incantations lorsque l’on subit des attaques.",
  ["Aide à retrouver rapidement un démon après sa perte."] = "Aide à retrouver rapidement un démon après sa perte.",
  ["Aide à retrouver sa mobilité pour poursuivre ou se dégager."] = "Aide à retrouver sa mobilité pour poursuivre ou se dégager.",
  ["Aide à récupérer de la mana entre les ennemis ou les engagements PvP."] = "Aide à récupérer de la mana entre les ennemis ou les engagements PvP.",
  ["Aider dans un autre rôle ne remplace pas un équipement et des talents adaptés."] = "Aider dans un autre rôle ne remplace pas un équipement et des talents adaptés.",
  ["Ajouter ECO / OPTIONAL et PVP / PVE PVP aux sorts renseignés dans la liste de classe de TrainerSpells, selon tes rôles et réglages. Son propre affichage de disponibilité reste conservé."] = "Ajouter ECO / OPTIONAL et PVP / PVE PVP aux sorts renseignés dans la liste de classe de TrainerSpells, selon tes rôles et réglages. Son propre affichage de disponibilité reste conservé.",
  ["Ajouter les contours de statut chez le maître de classe et autour des livres reconnus chez le marchand et dans les sacs. Désactiver retire uniquement les contours de notre addon."] = "Ajouter les contours de statut chez le maître de classe et autour des livres reconnus chez le marchand et dans les sacs. Désactiver retire uniquement les contours de notre addon.",
  ["Ajouter un fond vert discret aux lignes apprenables, jaune aux prochains paliers et sombre aux sorts déjà appris. Ce réglage est indépendant des contours et des icônes ; il ne modifie pas le fond général des fenêtres."] = "Ajouter un fond vert discret aux lignes apprenables, jaune aux prochains paliers et sombre aux sorts déjà appris. Ce réglage est indépendant des contours et des icônes ; il ne modifie pas le fond général des fenêtres.",
  ["Ajouts de fonctionnalités"] = "Ajouts de fonctionnalités",
  ["Alternance de sorts qui donne du rythme au jeu à distance."] = "Alternance de sorts qui donne du rythme au jeu à distance.",
  ["Amélioration"] = "Amélioration",
  ["Amélioration associe les attaques de mêlée aux renforcements d'arme, aux totems et aux occasions de lancer des sorts sans leur préparation habituelle. Les attaques automatiques gardent une place importante, ce qui laisse le temps d'apprendre à gérer le soutien du groupe. À mesure que les talents arrivent, il faut aussi réagir aux charges et aux effets qui rendent certains sorts plus avantageux."] = "Amélioration associe les attaques de mêlée aux renforcements d'arme, aux totems et aux occasions de lancer des sorts sans leur préparation habituelle. Les attaques automatiques gardent une place importante, ce qui laisse le temps d'apprendre à gérer le soutien du groupe. À mesure que les talents arrivent, il faut aussi réagir aux charges et aux effets qui rendent certains sorts plus avantageux.",
  ["Amélioration est un choix pratique dès les premiers niveaux : ses attaques d'arme, ses renforcements et ses soins permettent une progression autonome. Élémentaire reste une alternative à distance, plus attentive à sa dépense de mana."] = "Amélioration est un choix pratique dès les premiers niveaux : ses attaques d'arme, ses renforcements et ses soins permettent une progression autonome. Élémentaire reste une alternative à distance, plus attentive à sa dépense de mana.",
  ["Annuler"] = "Annuler",
  ["Aperçu : aucun contour de statut ajouté."] = "Aperçu : aucun contour de statut ajouté.",
  ["Aperçu : badge ajouté au-dessus du sort."] = "Aperçu : badge ajouté au-dessus du sort.",
  ["Aperçu : icône du sort seule, sans badge ajouté."] = "Aperçu : icône du sort seule, sans badge ajouté.",
  ["Aperçu : nom et informations d'origine, sans couleur ni annotation ajoutée."] = "Aperçu : nom et informations d'origine, sans couleur ni annotation ajoutée.",
  ["Aperçu : |cff555555Sort appris|r  |cffff2626Sort indisponible|r  |cff40ff40[Already in your Bag]|r"] = "Aperçu : |cff555555Sort appris|r  |cffff2626Sort indisponible|r  |cff40ff40[Already in your Bag]|r",
  ["Aperçu schématique : |cff00ff00[ Apprenable ]|r  |cffffd100[ Prochain palier ]|r  |cffff3333[ Indisponible ]|r  |cff888888[ Appris ]|r"] = "Aperçu schématique : |cff00ff00[ Apprenable ]|r  |cffffd100[ Prochain palier ]|r  |cffff3333[ Indisponible ]|r  |cff888888[ Appris ]|r",
  ["Apprentissages récents"] = "Apprentissages récents",
  ["Arbre de talents"] = "Arbre de talents",
  ["Arcanes"] = "Arcanes",
  ["Arcanes fait de la mana une ressource à dépenser au bon moment : certains sorts augmentent la pression offensive mais rendent les enchaînements coûteux. Il faut alterner les phases de dépense avec des attaques plus économes et profiter des effets déclenchés par les talents. Le bon rythme dépend notamment de la durée du combat."] = "Arcanes fait de la mana une ressource à dépenser au bon moment : certains sorts augmentent la pression offensive mais rendent les enchaînements coûteux. Il faut alterner les phases de dépense avec des attaques plus économes et profiter des effets déclenchés par les talents. Le bon rythme dépend notamment de la durée du combat.",
  ["Armes"] = "Armes",
  ["Armes permet de se concentrer sur une bonne arme à deux mains. Fureur est une autre option, avec de nouveaux outils de récupération de vie, mais dépend fortement des armes et de l'équipement. Les deux demandent des combats bien choisis."] = "Armes permet de se concentrer sur une bonne arme à deux mains. Fureur est une autre option, avec de nouveaux outils de récupération de vie, mais dépend fortement des armes et de l'équipement. Les deux demandent des combats bien choisis.",
  ["Armes privilégie des coups puissants avec une arme à deux mains, tout en profitant de saignements et d'occasions d'attaquer. La rage gagnée au combat doit être utilisée au bon moment plutôt que dépensée sans réserve. Le guerrier dispose aussi de déplacements rapides et de contrôles qui l'aident à rester au contact de ses adversaires."] = "Armes privilégie des coups puissants avec une arme à deux mains, tout en profitant de saignements et d'occasions d'attaquer. La rage gagnée au combat doit être utilisée au bon moment plutôt que dépensée sans réserve. Le guerrier dispose aussi de déplacements rapides et de contrôles qui l'aident à rester au contact de ses adversaires.",
  ["Arrêter un lanceur de sorts peut aider en donjon comme en PvP."] = "Arrêter un lanceur de sorts peut aider en donjon comme en PvP.",
  ["Assassinat"] = "Assassinat",
  ["Assassinat construit des points de combo avec ses attaques, puis les dépense surtout pour entretenir ses principaux effets offensifs. Dans Forever, le rythme décrit par le guide repose davantage sur le suivi de ces effets que sur une longue liste de grandes capacités à déclencher. C'est une approche assez directe, mais qui demande de surveiller son énergie et ses renouvellements."] = "Assassinat construit des points de combo avec ses attaques, puis les dépense surtout pour entretenir ses principaux effets offensifs. Dans Forever, le rythme décrit par le guide repose davantage sur le suivi de ces effets que sur une longue liste de grandes capacités à déclencher. C'est une approche assez directe, mais qui demande de surveiller son énergie et ses renouvellements.",
  ["Attaque centrale du jeu Amélioration en PvE comme en PvP."] = "Attaque centrale du jeu Amélioration en PvE comme en PvP.",
  ["Attaque de Destruction utile dans les deux activités."] = "Attaque de Destruction utile dans les deux activités.",
  ["Attaque instantanée utilisée en PvE et pour finir un adversaire en PvP."] = "Attaque instantanée utilisée en PvE et pour finir un adversaire en PvP.",
  ["Attaque majeure en Armes ; sa pression sur les soins est précieuse en PvP."] = "Attaque majeure en Armes ; sa pression sur les soins est précieuse en PvP.",
  ["Aucun apprentissage enregistré."] = "Aucun apprentissage enregistré.",
