  ["Automatique (client du jeu)"] = "Automatique (client du jeu)",
  ["Avant le niveau 10, survoler un onglet de spécialisation du grimoire présente son résumé, ses avantages et ses inconvénients."] = "Avant le niveau 10, survoler un onglet de spécialisation du grimoire présente son résumé, ses avantages et ses inconvénients.",
  ["Avantages"] = "Avantages",
  ["Avantages et limites synthétisés depuis le gameplay décrit ; la rubrique dédiée du guide est absente ou incomplète."] = "Avantages et limites synthétisés depuis le gameplay décrit ; la rubrique dédiée du guide est absente ou incomplète.",
  ["Avec TrainerSpells actif, les textes du maître de classe restent sous son contrôle même si cette case est cochée. Les réglages des autres catégories restent indépendants."] = "Avec TrainerSpells actif, les textes du maître de classe restent sous son contrôle même si cette case est cochée. Les réglages des autres catégories restent indépendants.",
