  ["Identifier chez le marchand les grimoires déjà présents dans les sacs, avec une mention et un contour vert."] = "Identifier chez le marchand les grimoires déjà présents dans les sacs, avec une mention et un contour vert.",
  ["Identifier les grimoires démonistes déjà appris ou apprenables dans les sacs Blizzard et EllesmereUI, avec des marqueurs de démon et d’apprentissage."] = "Identifier les grimoires démonistes déjà appris ou apprenables dans les sacs Blizzard et EllesmereUI, avec des marqueurs de démon et d’apprentissage.",
  ["Identifier les sorts du maître de classe avec NEW +, une coche verte, NEXT ou NOT NOW ; NEW + peut afficher un halo lumineux."] = "Identifier les sorts du maître de classe avec NEW +, une coche verte, NEXT ou NOT NOW ; NEW + peut afficher un halo lumineux.",
  ["Identifier les sorts déjà appris chez les maîtres de classe grâce à un texte gris et un fond assombri."] = "Identifier les sorts déjà appris chez les maîtres de classe grâce à un texte gris et un fond assombri.",
  ["Il faut gérer la mana, les charges offensives et le placement des totems."] = "Il faut gérer la mana, les charges offensives et le placement des totems.",
