  ["Report possible en leveling Ombre; capacite sur cibles de haut niveau, menace, soin/groupe a verifier. Pas equivalence de tous les rangs."] = "Report possible en leveling Ombre; capacite sur cibles de haut niveau, menace, soin/groupe a verifier. Pas equivalence de tous les rangs.",
  ["Report propose par le guide de leveling; Rain of Fire/Hellfire exige validation securite et AoE avant recommandation automatique."] = "Report propose par le guide de leveling; Rain of Fire/Hellfire exige validation securite et AoE avant recommandation automatique.",
  ["Reporter cet achat permet d'économiser de l'or pendant le leveling."] = "Reporter cet achat permet d'économiser de l'or pendant le leveling.",
  ["Repère d’usage, pas une obligation de talent ou d’achat."] = "Repère d’usage, pas une obligation de talent ou d’achat.",
  ["Repérer BUY NEW RANK lorsqu’un rang supérieur accessible reste à apprendre, hors achats classés ECO ou OPTIONAL."] = "Repérer BUY NEW RANK lorsqu’un rang supérieur accessible reste à apprendre, hors achats classés ECO ou OPTIONAL.",
  ["Repérer dans le grimoire BEST (plus haut rang appris), LOW (ancien rang appris), ECO (rang suffisant pour l’usage conseillé) et OPTIONAL (achat facultatif selon ses rôles)."] = "Repérer dans le grimoire BEST (plus haut rang appris), LOW (ancien rang appris), ECO (rang suffisant pour l’usage conseillé) et OPTIONAL (achat facultatif selon ses rôles).",
  ["Repérer les exemplaires déjà possédés grâce aux dernières positions connues dans les sacs, la banque et la banque de guilde."] = "Repérer les exemplaires déjà possédés grâce aux dernières positions connues dans les sacs, la banque et la banque de guilde.",
  ["Repérer les grimoires déjà appris et apprenables chez les marchands avec une icône de démon et des marqueurs de livre."] = "Repérer les grimoires déjà appris et apprenables chez les marchands avec une icône de démon et des marqueurs de livre.",
  ["Repérer les sorts déjà connus et apprenables chez le maître de classe grâce à des marqueurs sur les icônes."] = "Repérer les sorts déjà connus et apprenables chez le maître de classe grâce à des marqueurs sur les icônes.",
  ["Resistances selon contenu; aucune extrapolation a une ligne vide du tableau."] = "Resistances selon contenu; aucune extrapolation a une ligne vide du tableau.",
  ["Resistances selon zone/groupe; Frostbrand selon PvP; pas de skip si besoin specifique."] = "Resistances selon zone/groupe; Frostbrand selon PvP; pas de skip si besoin specifique.",
  ["Restauration"] = "Restauration",
  ["Restauration s'appuie beaucoup sur des soins qui continuent d'agir pendant plusieurs secondes. Le joueur anticipe les dégâts, répartit ses effets sur les bons alliés et les complète avec des soins directs lorsque la situation l'exige. Sa force vient du suivi des cibles et de la préparation plutôt que d'une réaction identique à chaque perte de vie."] = "Restauration s'appuie beaucoup sur des soins qui continuent d'agir pendant plusieurs secondes. Le joueur anticipe les dégâts, répartit ses effets sur les bons alliés et les complète avec des soins directs lorsque la situation l'exige. Sa force vient du suivi des cibles et de la préparation plutôt que d'une réaction identique à chaque perte de vie.",
  ["Restauration si tu progresses régulièrement en soignant un groupe. Amélioration ou Élémentaire conviennent pour jouer DPS tout en apportant les totems."] = "Restauration si tu progresses régulièrement en soignant un groupe. Amélioration ou Élémentaire conviennent pour jouer DPS tout en apportant les totems.",
  ["Restauration soigne avec un mélange de soins directs, d'effets sur la durée et de soins qui rebondissent entre les alliés. Les totems complètent ce travail en apportant des bonus et du soutien. Forever enrichit cette base sans en changer l'idée principale : choisir le bon soin pour les blessés et maintenir ses outils de groupe en bonne position."] = "Restauration soigne avec un mélange de soins directs, d'effets sur la durée et de soins qui rebondissent entre les alliés. Les totems complètent ce travail en apportant des bonus et du soutien. Forever enrichit cette base sans en changer l'idée principale : choisir le bon soin pour les blessés et maintenir ses outils de groupe en bonne position.",
  ["Restauration soin; acheter les degats si leveling solo. Le guide cite des rangs tardifs, pas une preuve que le rang 1 suffit."] = "Restauration soin; acheter les degats si leveling solo. Le guide cite des rangs tardifs, pas une preuve que le rang 1 suffit.",
  ["Retenir des ennemis peut protéger le groupe ou empêcher un joueur de poursuivre."] = "Retenir des ennemis peut protéger le groupe ou empêcher un joueur de poursuivre.",
  ["Retrouver certains outils peut aider à survivre ou relancer une offensive."] = "Retrouver certains outils peut aider à survivre ou relancer une offensive.",
  ["Retrouver dans les infobulles les indications d’apprentissage et de niveau de déblocage du familier."] = "Retrouver dans les infobulles les indications d’apprentissage et de niveau de déblocage du familier.",
  ["Retrouver les conseils ECO et OPTIONAL chez le maître de classe et dans les infobulles de sorts reconnues, y compris hors du grimoire."] = "Retrouver les conseils ECO et OPTIONAL chez le maître de classe et dans les infobulles de sorts reconnues, y compris hors du grimoire.",
  ["Retrouver sa peur plus souvent aide surtout à se dégager des joueurs."] = "Retrouver sa peur plus souvent aide surtout à se dégager des joueurs.",
  ["Retrouver son étourdissement plus souvent aide à gérer une menace."] = "Retrouver son étourdissement plus souvent aide à gérer une menace.",
  ["Rythme actif, avec des dégâts réguliers et de nombreux contrôles."] = "Rythme actif, avec des dégâts réguliers et de nombreux contrôles.",
  ["Réactiver les catégories d'affichage et les conseils. Les rôles sont reproposés selon tes talents actuels ou le leveling conseillé."] = "Réactiver les catégories d'affichage et les conseils. Les rôles sont reproposés selon tes talents actuels ou le leveling conseillé.",
  ["Réactivité pour un soin ou un sort urgent dans les deux activités."] = "Réactivité pour un soin ou un sort urgent dans les deux activités.",
  ["Récupération de vie limitée et gestion des ressources nécessaire sur la durée."] = "Récupération de vie limitée et gestion des ressources nécessaire sur la durée.",
  ["Réinitialisation"] = "Réinitialisation",
  ["Réinitialisation effectuée. Recharger l'interface maintenant ?\nAvec « Plus tard », tes choix sont conservés et tu peux utiliser /reload quand tu le souhaites."] = "Réinitialisation effectuée. Recharger l'interface maintenant ?\nAvec « Plus tard », tes choix sont conservés et tu peux utiliser /reload quand tu le souhaites.",
  ["Réponse immédiate pour soigner ou infliger des dégâts."] = "Réponse immédiate pour soigner ou infliger des dégâts.",
  ["Résister aux contrôles est surtout utile face aux joueurs."] = "Résister aux contrôles est surtout utile face aux joueurs.",
  ["Résurrection : le rang 1 permet de ressusciter ; les rangs suivants rendent davantage de vie et de mana."] = "Résurrection : le rang 1 permet de ressusciter ; les rangs suivants rendent davantage de vie et de mana.",
  ["Rétablir l'affichage, les conseils et les choix de rôle par défaut pour ce personnage ?"] = "Rétablir l'affichage, les conseils et les choix de rôle par défaut pour ce personnage ?",
  ["Rétablir les options ou relancer le premier lancement depuis Réinitialisation, avec confirmation puis Recharger l’interface / Plus tard."] = "Rétablir les options ou relancer le premier lancement depuis Réinitialisation, avec confirmation puis Recharger l’interface / Plus tard.",
  ["Rétablir les options par défaut"] = "Rétablir les options par défaut",
  ["Rétablis les réglages ou teste à nouveau le premier lancement. Les sorts du familier et les livres enregistrés sont conservés."] = "Rétablis les réglages ou teste à nouveau le premier lancement. Les sorts du familier et les livres enregistrés sont conservés.",
  ["Rôles et spécialisations"] = "Rôles et spécialisations",
  ["Rôles et talents : résumés des spécialisations, recommandation LEVELING et repères PVP / PVE PVP sur les entrées renseignées."] = "Rôles et talents : résumés des spécialisations, recommandation LEVELING et repères PVP / PVE PVP sur les entrées renseignées.",
  ["Sacre soin; tanking hybride, generation de menace et controle changent les priorites."] = "Sacre soin; tanking hybride, generation de menace et controle changent les priorites.",
  ["Sacré"] = "Sacré",
  ["Sacré privilégie les soins tout en conservant les protections, bénédictions et auras du paladin. Forever ajoute des interactions permettant de mieux répondre aux dégâts de groupe, en plus des soins ciblés. Le fonctionnement de base est accessible, mais il faut progressivement apprendre à choisir les bons outils de soutien et à gérer ses sceaux."] = "Sacré privilégie les soins tout en conservant les protections, bénédictions et auras du paladin. Forever ajoute des interactions permettant de mieux répondre aux dégâts de groupe, en plus des soins ciblés. Le fonctionnement de base est accessible, mais il faut progressivement apprendre à choisir les bons outils de soutien et à gérer ses sceaux.",
  ["Sacré propose une large palette de soins pour répondre aux dégâts subis par un allié ou par le groupe. Forever ajoute notamment des outils qui soignent plusieurs personnes ou rebondissent entre les alliés, tout en conservant les soins directs classiques. Le joueur adapte son sort à l'urgence, au nombre de blessés et à sa réserve de mana."] = "Sacré propose une large palette de soins pour répondre aux dégâts subis par un allié ou par le groupe. Forever ajoute notamment des outils qui soignent plusieurs personnes ou rebondissent entre les alliés, tout en conservant les soins directs classiques. Le joueur adapte son sort à l'urgence, au nombre de blessés et à sa réserve de mana.",
  ["Sacs et banques"] = "Sacs et banques",
  ["Select All"] = "Tout sélectionner",
  ["Seulement si aucun tanking prevu."] = "Seulement si aucun tanking prevu.",
  ["Signaler les achats facultatifs chez le maître de classe et dans les infobulles ; dans le grimoire, OPTIONAL se place à droite de BEST. Pendant le leveling (avant le niveau 60), selon tous tes rôles et spécialisations. L'infobulle distingue le sort facultatif, le rang supplémentaire reportable et le cas où le rang 1 suffit pour l'usage conseillé, sans afficher les notes de recherche. Ce conseil ne retire aucun sort et reste indépendant d'ECO. La case Icônes doit aussi être activée pour voir le badge."] = "Signaler les achats facultatifs chez le maître de classe et dans les infobulles ; dans le grimoire, OPTIONAL se place à droite de BEST. Pendant le leveling (avant le niveau 60), selon tous tes rôles et spécialisations. L'infobulle distingue le sort facultatif, le rang supplémentaire reportable et le cas où le rang 1 suffit pour l'usage conseillé, sans afficher les notes de recherche. Ce conseil ne retire aucun sort et reste indépendant d'ECO. La case Icônes doit aussi être activée pour voir le badge.",
  ["Signaler les rangs supérieurs à acheter"] = "Signaler les rangs supérieurs à acheter",
  ["Signaler les recettes déjà apprises"] = "Signaler les recettes déjà apprises",
  ["Signaler les sorts, talents et recettes récemment appris. La liste est conservée après rechargement et remplacée lorsqu’un nouvel apprentissage est enregistré. Une visite sans achat conserve la liste précédente. À la première utilisation, les sorts déjà connus du dernier palier accessible sont présélectionnés si leurs niveaux sont connus."] = "Signaler les sorts, talents et recettes récemment appris. La liste est conservée après rechargement et remplacée lorsqu’un nouvel apprentissage est enregistré. Une visite sans achat conserve la liste précédente. À la première utilisation, les sorts déjà connus du dernier palier accessible sont présélectionnés si leurs niveaux sont connus.",
  ["Skills Already Known devient Skills & More. Retrouve le nouveau nom dans les options, la minicarte et les infobulles, avec la signature By CryptoLogiq dans la fenêtre des options."] = "Skills Already Known devient Skills & More. Retrouve le nouveau nom dans les options, la minicarte et les infobulles, avec la signature By CryptoLogiq dans la fenêtre des options.",
  ["Soigner les alliés pour maintenir le groupe en vie."] = "Soigner les alliés pour maintenir le groupe en vie.",
  ["Soin en groupe; les degats peuvent compter en solo. Ne pas marquer le premier achat de Resurrection."] = "Soin en groupe; les degats peuvent compter en solo. Ne pas marquer le premier achat de Resurrection.",
  ["Soins ciblés et soins sur plusieurs alliés dans une même boîte à outils."] = "Soins ciblés et soins sur plusieurs alliés dans une même boîte à outils.",
  ["Soins ciblés, soutien varié et nouveaux outils pour le groupe."] = "Soins ciblés, soutien varié et nouveaux outils pour le groupe.",
  ["Sorts / compétences"] = "Sorts / compétences",
  ["Sorts du familier (/sam pet)"] = "Sorts du familier (/sam pet)",
  ["Souplesse pour exploiter les outils du chasseur et les capacités du familier."] = "Souplesse pour exploiter les outils du chasseur et les capacités du familier.",
  ["Soutien des totems et nouveaux outils de récupération de mana."] = "Soutien des totems et nouveaux outils de récupération de mana.",
  ["Soutien utile au groupe et progression solo accessible."] = "Soutien utile au groupe et progression solo accessible.",
  ["Soutien varié : bonus, affaiblissements, contrôles et soins de secours."] = "Soutien varié : bonus, affaiblissements, contrôles et soins de secours.",
  ["Spécialisation"] = "Spécialisation",
  ["Spécialisation : "] = "Spécialisation : ",
  ["Spécialisation suivie pour ce rôle. La sélection est conservée si tu décoches puis recoches le rôle."] = "Spécialisation suivie pour ce rôle. La sélection est conservée si tu décoches puis recoches le rôle.",
  ["Survie"] = "Survie",
  ["Survie au contact, utile en solo et contre les joueurs."] = "Survie au contact, utile en solo et contre les joueurs.",
  ["Survie face aux attaques au corps à corps, dans les deux activités."] = "Survie face aux attaques au corps à corps, dans les deux activités.",
  ["Survie personnelle utile sous les attaques, notamment en PvP et en solo."] = "Survie personnelle utile sous les attaques, notamment en PvP et en solo.",
  ["Survie propose un rythme offensif soutenu et utilise plus largement les possibilités du chasseur, à distance comme au corps à corps selon le combat et le choix de talents. Les pièges et les contrôles aident à gérer les déplacements ennemis. L'arbre prend davantage de relief une fois ses talents clés obtenus, plutôt que dès les tout premiers niveaux."] = "Survie propose un rythme offensif soutenu et utilise plus largement les possibilités du chasseur, à distance comme au corps à corps selon le combat et le choix de talents. Les pièges et les contrôles aident à gérer les déplacements ennemis. L'arbre prend davantage de relief une fois ses talents clés obtenus, plutôt que dès les tout premiers niveaux.",
  ["Sélection initiale : sorts déjà connus du palier de niveau "] = "Sélection initiale : sorts déjà connus du palier de niveau ",
  ["Talent Spec and Role"] = "Talents, spécialisation et rôle",
  ["Talents"] = "Talents",
  ["Temps fort offensif de la spécialisation Élémentaire."] = "Temps fort offensif de la spécialisation Élémentaire.",
  ["Temps fort offensif à utiliser en tenant compte du risque défensif."] = "Temps fort offensif à utiliser en tenant compte du risque défensif.",
  ["Totems et contrôles apportant du soutien au groupe."] = "Totems et contrôles apportant du soutien au groupe.",
  ["Un badge LEVELING signale l’arbre conseillé en priorité pour progresser en solo dans chaque classe. Les infobulles des arbres et du grimoire décrivent uniquement la spécialisation survolée."] = "Un badge LEVELING signale l’arbre conseillé en priorité pour progresser en solo dans chaque classe. Les infobulles des arbres et du grimoire décrivent uniquement la spécialisation survolée.",
  ["Un bon résultat demande de choisir quand protéger et quand soigner."] = "Un bon résultat demande de choisir quand protéger et quand soigner.",
  ["Un lanceur de sorts à distance qui affaiblit ses ennemis avec des dégâts sur la durée, puis utilise ses drains entre les renouvellements. Il peut entretenir ses effets sur plusieurs adversaires tout en s'appuyant sur son démon. Son efficacité augmente quand les combats lui laissent le temps d'installer et de maintenir ces effets."] = "Un lanceur de sorts à distance qui affaiblit ses ennemis avec des dégâts sur la durée, puis utilise ses drains entre les renouvellements. Il peut entretenir ses effets sur plusieurs adversaires tout en s'appuyant sur son démon. Son efficacité augmente quand les combats lui laissent le temps d'installer et de maintenir ces effets.",
  ["Un soin immédiat peut sauver un allié dans les deux activités."] = "Un soin immédiat peut sauver un allié dans les deux activités.",
  ["Une dépense trop rapide peut laisser le mage sans mana."] = "Une dépense trop rapide peut laisser le mage sans mana.",
  ["Une incantation instantanée apporte dégâts ou réactivité."] = "Une incantation instantanée apporte dégâts ou réactivité.",
  ["Une part de son utilité est commune aux autres spécialisations de chaman."] = "Une part de son utilité est commune aux autres spécialisations de chaman.",
  ["Une partie du résultat dépend de la fréquence des critiques."] = "Une partie du résultat dépend de la fréquence des critiques.",
  ["Une progression centrée sur les soins est surtout adaptée au jeu en groupe."] = "Une progression centrée sur les soins est surtout adaptée au jeu en groupe.",
  ["Utile en PvE et contre les joueurs, selon ta spécialisation et le combat."] = "Utile en PvE et contre les joueurs, selon ta spécialisation et le combat.",
  ["Utile selon la situation ; tu peux l'apprendre et l'utiliser."] = "Utile selon la situation ; tu peux l'apprendre et l'utiliser.",
  ["Utilitaire situationnel ; conserve son intérêt pour le butin ou les déplacements en camouflage."] = "Utilitaire situationnel ; conserve son intérêt pour le butin ou les déplacements en camouflage.",
  ["Utilitaire; ce sort n'est pas une economie de rangs multiples."] = "Utilitaire; ce sort n'est pas une economie de rangs multiples.",
  ["Utilitaire; conserver si interruption, fuite ou soutien de groupe. Pas ECO automatique."] = "Utilitaire; conserver si interruption, fuite ou soutien de groupe. Pas ECO automatique.",
  ["Valider mes choix"] = "Valider mes choix",
  ["Vindicte"] = "Vindicte",
  ["Vindicte est la voie de dégâts de mêlée du paladin : ses attaques avec une arme se combinent à des effets sacrés, aux sceaux et au Jugement. Il conserve les bénédictions, auras et protections qui lui permettent d'aider son groupe. Bien jouer consiste donc aussi à utiliser ce soutien au bon moment, sans abandonner inutilement sa pression offensive."] = "Vindicte est la voie de dégâts de mêlée du paladin : ses attaques avec une arme se combinent à des effets sacrés, aux sceaux et au Jugement. Il conserve les bénédictions, auras et protections qui lui permettent d'aider son groupe. Bien jouer consiste donc aussi à utiliser ce soutien au bon moment, sans abandonner inutilement sa pression offensive.",
  ["Vindicte est un choix simple et autonome pour les quêtes, avec des attaques régulières, des protections et des soins personnels. Garde une arme adaptée et surveille ta mana."] = "Vindicte est un choix simple et autonome pour les quêtes, avec des attaques régulières, des protections et des soins personnels. Garde une arme adaptée et surveille ta mana.",
  ["Voleur"] = "Voleur",
  ["Vérifier le récapitulatif avant d'activer les conseils pour ces rôles et spécialisations."] = "Vérifier le récapitulatif avant d'activer les conseils pour ces rôles et spécialisations.",
  ["Vérifier un récapitulatif des rôles et spécialisations avec OK / Annuler avant d’activer les conseils. Une sélection non validée est reproposée au prochain chargement."] = "Vérifier un récapitulatif des rôles et spécialisations avec OK / Annuler avant d’activer les conseils. Une sélection non validée est reproposée au prochain chargement.",
  ["[LEVELING] — choix conseillé pour progresser en solo"] = "[LEVELING] — choix conseillé pour progresser en solo",
  ["activé"] = "activé",
  ["désactivé"] = "désactivé",
  ["la dernière version"] = "la dernière version",
  ["|cff00ccffECO|r : rang suffisant pour le leveling selon ton rôle ; économie d'or en reportant des achats, pas d'économie de mana garantie."] = "|cff00ccffECO|r : rang suffisant pour le leveling selon ton rôle ; économie d'or en reportant des achats, pas d'économie de mana garantie.",
  ["|cff00ccffOPTIONAL|r : achat facultatif en leveling pour ton rôle. S'ajoute à droite de BEST ; L'infobulle rappelle qu'il s'agit d'une économie d'or sur un achat facultatif. Facultatif ne veut pas dire inutile."] = "|cff00ccffOPTIONAL|r : achat facultatif en leveling pour ton rôle. S'ajoute à droite de BEST ; L'infobulle rappelle qu'il s'agit d'une économie d'or sur un achat facultatif. Facultatif ne veut pas dire inutile.",
  ["|cff33ff33Avantages|r"] = "|cff33ff33Avantages|r",
  ["|cff33ff33BEST|r : plus haut rang appris, même s'il est seul ; puissance et effets de ce rang."] = "|cff33ff33BEST|r : plus haut rang appris, même s'il est seul ; puissance et effets de ce rang.",
  ["|cff33ff33NEW +|r : sort apprenable maintenant, contour vert et halo animé."] = "|cff33ff33NEW +|r : sort apprenable maintenant, contour vert et halo animé.",
  ["|cff4dff4dAvantages|r"] = "|cff4dff4dAvantages|r",
  ["|cffaaaaaaLOW|r : rang inférieur appris, aux dégâts, soins ou effets potentiellement réduits. Certains contrôles ont une limite de niveau."] = "|cffaaaaaaLOW|r : rang inférieur appris, aux dégâts, soins ou effets potentiellement réduits. Certains contrôles ont une limite de niveau.",
  ["|cffff3333NOT NOW|r : autre indisponibilité, contour rouge."] = "|cffff3333NOT NOW|r : autre indisponibilité, contour rouge.",
  ["|cffff5966[PVP]|r : principalement intéressant contre les joueurs. |cff59d9ff[PVE PVP]|r : utile dans les deux activités. Ces repères d’usage apparaissent sur les talents vérifiés et les sorts apprenables du maître ; ils ne rendent aucun choix obligatoire et restent indépendants d’ECO / OPTIONAL."] = "|cffff5966[PVP]|r : principalement intéressant contre les joueurs. |cff59d9ff[PVE PVP]|r : utile dans les deux activités. Ces repères d’usage apparaissent sur les talents vérifiés et les sorts apprenables du maître ; ils ne rendent aucun choix obligatoire et restent indépendants d’ECO / OPTIONAL.",
  ["|cffff7359Inconvénients|r"] = "|cffff7359Inconvénients|r",
  ["|cffffcc00Skills & More:|r configuration disponible après le combat."] = "|cffffcc00Skills & More:|r configuration disponible après le combat.",
  ["|cffffcc00Skills & More:|r utilise /reload après le combat."] = "|cffffcc00Skills & More:|r utilise /reload après le combat.",
  ["|cffffd100BUY NEW RANK|r : un rang supérieur accessible à ton niveau reste à apprendre. Les achats ECO / OPTIONAL ne déclenchent pas cette alerte. LOW signifie qu'un rang supérieur est déjà appris."] = "|cffffd100BUY NEW RANK|r : un rang supérieur accessible à ton niveau reste à apprendre. Les achats ECO / OPTIONAL ne déclenchent pas cette alerte. LOW signifie qu'un rang supérieur est déjà appris.",
  ["|cffffd100NEXT|r : disponible au prochain palier de niveau pair, contour et fond jaunes."] = "|cffffd100NEXT|r : disponible au prochain palier de niveau pair, contour et fond jaunes.",
  ["|cffffd100[LEVELING] — choix conseillé pour progresser en solo|r"] = "|cffffd100[LEVELING] — choix conseillé pour progresser en solo|r",
  ["À la première utilisation, RECENT présélectionne les sorts déjà connus du dernier palier accessible à ton niveau lorsque leurs niveaux requis sont disponibles. Les prochains apprentissages remplacent cette sélection initiale."] = "À la première utilisation, RECENT présélectionne les sorts déjà connus du dernier palier accessible à ton niveau lorsque leurs niveaux requis sont disponibles. Les prochains apprentissages remplacent cette sélection initiale.",
  ["À l’aise sur les combats longs et contre plusieurs ennemis séparés."] = "À l’aise sur les combats longs et contre plusieurs ennemis séparés.",
  ["Élémentaire"] = "Élémentaire",
  ["Élémentaire combat à distance avec des éclairs et des sorts de feu, tout en soutenant le groupe grâce aux totems. Les attaques qui touchent plusieurs ennemis proches tiennent une place importante dans son arsenal. Le rythme offensif reste abordable, mais les gros enchaînements peuvent coûter beaucoup de mana et demandent de bien placer ses totems."] = "Élémentaire combat à distance avec des éclairs et des sorts de feu, tout en soutenant le groupe grâce aux totems. Les attaques qui touchent plusieurs ennemis proches tiennent une place importante dans son arsenal. Le rythme offensif reste abordable, mais les gros enchaînements peuvent coûter beaucoup de mana et demandent de bien placer ses totems.",
  ["Éléments affichés"] = "Éléments affichés",
  ["Équilibre"] = "Équilibre",
  ["Équilibre joue à distance avec des sorts de nature et des arcanes, ainsi que des dégâts sur la durée. Les talents de Forever encouragent à alterner les grandes incantations selon les effets actifs. Le druide peut aussi interrompre son rythme offensif pour contrôler des ennemis ou apporter des soins de secours, au prix de temps et de mana."] = "Équilibre joue à distance avec des sorts de nature et des arcanes, ainsi que des dégâts sur la durée. Les talents de Forever encouragent à alterner les grandes incantations selon les effets actifs. Le druide peut aussi interrompre son rythme offensif pour contrôler des ennemis ou apporter des soins de secours, au prix de temps et de mana.",
  ["— conseillé pour progresser en solo"] = "— conseillé pour progresser en solo",
  ["Le choix manuel de langue est correctement repris après un rechargement de l’interface."] = "Le choix manuel de langue est correctement repris après un rechargement de l’interface.",
  ["La version officielle démarre correctement lorsque la copie DEV est présente mais non chargée."] = "La version officielle démarre correctement lorsque la copie DEV est présente mais non chargée.",
}
